    #include <iostream>
#include <vector>
using namespace std;

bool searchMatrix(vector<vector<int>>& mat, int x) {
    int n = mat.size(), m = mat[0].size();

    int lo = 0, hi = n * m - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;

        // find row and column of element at mid index
        int row = mid / m;
        int col = mid % m;

        // if x is found, return true
        if (mat[row][col] == x) 
            return true;

        // if x is greater than mat[row][col], search 
        // in right half
        if (mat[row][col] < x) 
            lo = mid + 1;

        // if x is less than mat[row][col], search 
        // in left half
        else 
            hi = mid - 1;
    }
    return false;
}

